from music21 import stream, note, chord, meter, tempo, key, instrument, dynamics, pitch
import random

random.seed(21)

# ---------------- basic material ----------------
BPM = 66
scale = ['D4','E4','F4','G4','A4','B4','C5','D5','E5','F5','G5','A5','B5','C6']

# harmonic plan (one triad per bar), 32 bars, D dorian with a few colourings
roots = ['D','D','D','D',
         'D','F','C','G','D','F','A','D',
         'D','Bb','F','C','G','Bb','A','D',
         'F','C','G','A','D','F','Bb','A',
         'D','D','D','D']
triad_map = {
    'D':  ['D','F','A'],
    'F':  ['F','A','C'],
    'C':  ['C','E','G'],
    'G':  ['G','B','D'],
    'Bb': ['B-','D','F'],
    'A':  ['A','C','E'],
}

rhythms = [
    [1,1,2],[2,1,1],[0.5,0.5,1,2],[1.5,0.5,2],[0.5,0.5,0.5,0.5,2],
    [3,1],[1,1,1,1],[2,2],[4],[1,0.5,0.5,2],[2,0.5,0.5,1]
]

def nearest_chord_index(idx, chord_pcs):
    best = idx
    bestd = 99
    for i, p in enumerate(scale):
        if pitch.Pitch(p).name in chord_pcs:
            d = abs(i - idx)
            if d < bestd:
                bestd = d
                best = i
    return best

# generate melody as list of bars, each bar a list of (scale_index or None, ql)
melody_bars = []
idx = 7  # D5
for bar in range(32):
    chord_pcs = triad_map[roots[bar]]
    rh = random.choice(rhythms)
    bar_notes = []
    for k, ql in enumerate(rh):
        if k == 0 and random.random() < 0.7:
            idx = nearest_chord_index(idx + random.choice([-1,0,0,1]), chord_pcs)
        else:
            step = random.choice([-2,-1,-1,0,1,1,2,3,-3])
            idx += step
        idx = max(2, min(len(scale)-1, idx))
        if random.random() < 0.08 and k != 0:
            bar_notes.append((None, ql))
        else:
            bar_notes.append((idx, ql))
    melody_bars.append(bar_notes)

def bar_to_notes(bar_notes, transpose=0, invert_center=None):
    out = []
    for i, ql in bar_notes:
        if i is None:
            out.append(note.Rest(quarterLength=ql))
        else:
            if invert_center is not None:
                i = invert_center - (i - invert_center)
                i = max(0, min(len(scale)-1, i))
            n = note.Note(scale[i], quarterLength=ql)
            if transpose:
                n = n.transpose(transpose)
            out.append(n)
    return out

# ---------------- parts ----------------
score = stream.Score()

rh = stream.Part(); rh.insert(0, instrument.Piano())
lh = stream.Part(); lh.insert(0, instrument.Piano())
vln = stream.Part(); vln.insert(0, instrument.Violin())
vc = stream.Part(); vc.insert(0, instrument.Violoncello())

for p in (rh, lh, vln, vc):
    p.append(tempo.MetronomeMark(number=BPM))
    p.append(meter.TimeSignature('4/4'))
    p.append(key.KeySignature(-1))

# left hand ostinato
lh.append(dynamics.Dynamic('pp'))
for bar in range(32):
    t = triad_map[roots[bar]]
    if bar >= 28:
        c = chord.Chord([t[0]+'2', t[0]+'3', t[2]+'3', t[1]+'4'], quarterLength=4)
        lh.append(c)
        continue
    if bar == 4:
        lh.append(dynamics.Dynamic('p'))
    if bar == 12:
        lh.append(dynamics.Dynamic('mp'))
    if bar == 24:
        lh.append(dynamics.Dynamic('mf'))
    pattern = [t[0]+'2', t[2]+'2', t[0]+'3', t[1]+'3', t[2]+'3', t[1]+'3', t[0]+'3', t[2]+'2']
    if bar >= 20 and bar < 28:
        pattern = [t[0]+'2', t[0]+'3', t[2]+'3', t[1]+'4', t[2]+'4', t[1]+'4', t[2]+'3', t[0]+'3']
    for pn in pattern:
        lh.append(note.Note(pn, quarterLength=0.5))

# right hand melody: silent first 4 bars, then melody, final bars sustained
rh.append(dynamics.Dynamic('p'))
for bar in range(32):
    if bar < 4:
        rh.append(note.Rest(quarterLength=4))
    elif bar < 28:
        if bar == 12:
            rh.append(dynamics.Dynamic('mp'))
        if bar == 20:
            rh.append(dynamics.Dynamic('mf'))
        for n in bar_to_notes(melody_bars[bar]):
            rh.append(n)
    elif bar < 31:
        rh.append(dynamics.Dynamic('p'))
        rh.append(chord.Chord(['A4','D5','E5'], quarterLength=4))
    else:
        rh.append(dynamics.Dynamic('pp'))
        rh.append(chord.Chord(['D5','A5'], quarterLength=4))

# cello: echoes the right hand two bars later, an octave lower (the "context")
vc.append(dynamics.Dynamic('p'))
for bar in range(32):
    if bar < 12:
        vc.append(note.Rest(quarterLength=4))
    elif bar < 28:
        for n in bar_to_notes(melody_bars[bar-2], transpose=-12):
            vc.append(n)
    else:
        vc.append(note.Note('D2', quarterLength=4))

# violin: inverted version of the melody, one bar later, high register
vln.append(dynamics.Dynamic('mp'))
for bar in range(32):
    if bar < 20:
        vln.append(note.Rest(quarterLength=4))
    elif bar < 28:
        for n in bar_to_notes(melody_bars[bar-1], transpose=12, invert_center=7):
            vln.append(n)
    elif bar < 31:
        vln.append(note.Note('A5', quarterLength=4))
    else:
        vln.append(dynamics.Dynamic('pp'))
        vln.append(note.Note('D6', quarterLength=4))

for p in (vln, rh, lh, vc):
    p.makeMeasures(inPlace=True)

score.insert(0, vln)
score.insert(0, rh)
score.insert(0, lh)
score.insert(0, vc)

