def add_measure(part, m_num, events, dyn=None):
    m = stream.Measure(number=m_num)
    if m_num == 1:
        m.insert(0, meter.TimeSignature('6/8'))
        m.insert(0, key.Key('d'))
    if dyn:
        m.insert(0, dynamics.Dynamic(dyn))

    offset = 0.0
    for pitch_data, dur in events:
        if pitch_data is None or pitch_data == 'R':
            el = note.Rest(quarterLength=dur)
        elif isinstance(pitch_data, list):
            el = chord.Chord(pitch_data, quarterLength=dur)
        else:
            el = note.Note(pitch_data, quarterLength=dur)
        m.insert(offset, el)
        offset += dur
    part.append(m)

