# 40 measures of 5/4 at 120 BPM = 200 beats = 100 seconds
for m_idx in range(40):
    m_v = stream.Measure(number=m_idx + 1)
    m_c = stream.Measure(number=m_idx + 1)
    m_p = stream.Measure(number=m_idx + 1)

    if m_idx == 0:
        for m in (m_v, m_c, m_p):
            m.insert(0, meter.TimeSignature('5/4'))
            m.insert(0, key.Key('C'))
        m_p.insert(0, dynamics.Dynamic('mp'))

    if m_idx == 8:
        m_v.insert(0, dynamics.Dynamic('p'))
        m_c.insert(0, dynamics.Dynamic('mp'))
    elif m_idx == 16:
        m_v.insert(0, dynamics.Dynamic('mf'))
        m_c.insert(0, dynamics.Dynamic('mf'))
        m_p.insert(0, dynamics.Dynamic('mf'))
    elif m_idx == 24:
        m_v.insert(0, dynamics.Dynamic('f'))
        m_c.insert(0, dynamics.Dynamic('f'))
        m_p.insert(0, dynamics.Dynamic('f'))
