    elif m_idx == 36:
        m_v.insert(0, dynamics.Dynamic('pp'))
        m_c.insert(0, dynamics.Dynamic('pp'))
        m_p.insert(0, dynamics.Dynamic('pp'))

    h = prog[m_idx % 4]
    cycle = m_idx // 4
    step = m_idx % 4

    # --- PIANO PART ---
    if m_idx < 24:
        for i, p_str in enumerate(h['p_notes']):
            n = note.Note(p_str, quarterLength=0.5)
            if cycle >= 4 and i in (4, 9):
                n.transpose(12, inPlace=True)
            m_p.append(n)
