        c1 = chord.Chord(h['chords'][0], quarterLength=1.5)
        c2 = chord.Chord(h['chords'][1], quarterLength=1.5)
        c3 = chord.Chord(h['chords'][0], quarterLength=1.0)
        c4 = chord.Chord(h['chords'][1], quarterLength=1.0)
        for c_obj in (c1, c2, c3, c4):
            m_p.append(c_obj)
    elif m_idx < 39:
        for i, p_str in enumerate(h['p_notes']):
            if m_idx >= 36 and i % 2 == 1:
                m_p.append(note.Rest(quarterLength=0.5))
            else:
                n = note.Note(p_str, quarterLength=0.5)
                if m_idx >= 36:
                    n.transpose(12, inPlace=True)
                m_p.append(n)
