        m_c.append(note.Rest(quarterLength=5.0))
    elif m_idx < 16:
        n1 = note.Note(h['c_root'], quarterLength=3.0)
        n2 = note.Note(h['c_fifth'], quarterLength=2.0)
        m_c.append(n1)
