        n1 = note.Note(h['c_root'], quarterLength=1.5)
        n2 = note.Note(h['c_fifth'], quarterLength=1.5)
        n3 = note.Note(h['c_arp'][3], quarterLength=1.0)
        n4 = note.Note(h['c_arp'][2], quarterLength=1.0)
        for n_obj in (n1, n2, n3, n4):
