    elif m_idx < 39:
        n1 = note.Note(h['c_root'], quarterLength=5.0)
        m_c.append(n1)
    else:
        m_c.append(note.Note('F2', quarterLength=5.0))

    # --- VIOLIN PART ---
    if m_idx < 8:
        m_v.append(note.Rest(quarterLength=5.0))
    elif m_idx < 16:
        if step == 0:
            m_v.append(note.Rest(quarterLength=2.0))
            m_v.append(note.Note('E5', quarterLength=3.0))
        elif step == 1:
            m_v.append(note.Note('D5', quarterLength=3.0))
            m_v.append(note.Note('B4', quarterLength=2.0))
