            m_v.append(note.Rest(quarterLength=1.0))
            m_v.append(note.Note('G4', quarterLength=2.0))
            m_v.append(note.Note('A4', quarterLength=2.0))
        else:
            m_v.append(note.Note('E5', quarterLength=5.0))
    elif m_idx < 24:
        if step == 0:
            v_notes = [('A5', 1.5), ('G5', 1.5), ('E5', 1.0), ('C5', 1.0)]
