            else:
                v_notes = [('E5', 1.5), ('G5', 1.5), ('A5', 2.0)]
        for p_str, ql in v_notes:
            m_v.append(note.Note(p_str, quarterLength=ql))
    elif m_idx < 32:
        if step == 0:
            v_notes = [('E6', 2.0), ('D6', 1.0), ('C6', 1.0), ('A5', 1.0)]
        elif step == 1:
            v_notes = [('D6', 1.5), ('B5', 1.5), ('A5', 1.0), ('G5', 1.0)]
